      {
       "type": "example",
       "title": "例題：水杯和皮球",
       "html": "水杯上下是兩個平平的圓面，側面是彎的，可以站穩，所以是<b>圓柱</b>。<br>皮球沒有平面，向任何方向推都會滾，所以是<b>球</b>。"
      },
      {
       "type": "text",
       "html": "正方形和正方體容易混淆：正方形是平面圖形，只有一個面；正方體是立體圖形，有 6 個正方形面。"
      },
      {
       "type": "tip",
       "html": "常犯錯誤：把圓柱當作球，因為兩者都會滾。圓柱只可以向一個方向滾，而且有兩個平面。"
      }
