     "id": "p2-u3",
     "title": "兩位數減法（含退位）",
     "en": "Subtraction of 2-digit Numbers with Borrowing",
     "strand": "數與代數",
     "objectives": [
      "能用直式計算兩位數減法",
      "能處理個位不夠減的退位情況",
      "能用加法驗算減法結果",
      "能解決兩位數減法的應用題"
     ],
     "teaching": [
      {
       "type": "text",
       "html": "減法直式同樣要個位對個位。如果個位的數不夠減，就要向十位<b>借 1 個十</b>，借來的 1 個十變成 10 個一，加在個位上。"
      },
      {
       "type": "text",
       "html": "借位之後，十位的數字要減 1。例如 52 − 37：個位 2 不夠減 7，向十位借 1，個位變成 12，十位由 5 變成 4。"
      },
      {
       "type": "formula",
       "html": "52 − 37 = 15（12 − 7 = 5，4 − 3 = 1）"
      },
      {
       "type": "example",
       "title": "例題：82 − 47",
       "html": "第一步：個位 2 不夠減 7，向十位借 1，個位變成 12。12 − 7 = 5。<br>第二步：十位本來是 8，借出 1 後是 7。7 − 4 = 3。<br>所以 <b>82 − 47 = 35</b>。<br>驗算：35 + 47 = 82，答案正確。"
      },
      {
       "type": "tip",
       "html": "常犯錯誤：借位後忘記把十位減 1，把 82 − 47 算成 45。借位時最好在十位數字上畫一撇做記號。"
      },
      {
       "type": "text",
       "html": "驗算方法：減法用加法驗算，把「差 + 減數」算一次，看是否等於被減數。這個習慣可以抓出大部分計算錯誤。"
      }
     ],
     "keywords": [
      "退位",
      "借位",
      "驗算",
      "差"
     ]
