       "type": "example",
       "title": "例題：45 粒糖每 6 粒裝一袋",
       "html": "第一步：想 6 的乘法表，6 × 7 = 42，6 × 8 = 48。48 超過 45，所以最多裝 7 袋。<br>第二步：7 袋用了 7 × 6 = 42 粒。<br>第三步：45 − 42 = 3，餘下 3 粒。<br>所以是 <b>7 袋，餘 3 粒</b>，寫成 45 ÷ 6 = 7 餘 3。驗算：7 × 6 + 3 = 45。"
