     "teaching": [
      {
       "type": "text",
       "html": "兩位數乘兩位數可以<b>分拆</b>：把第二個因數拆成「幾個十」和「幾個一」。例如 23 × 14 就是 23 × 10 再加 23 × 4。"
      },
      {
       "type": "formula",
       "html": "23 × 14 = 23 × 10 + 23 × 4 = 230 + 92 = 322"
      },
      {
       "type": "text",
       "html": "直式分兩行寫：第一行用個位去乘，第二行用十位去乘。用十位乘時，積要向左移一格（即末尾補 0），因為那是「幾個十」。最後把兩行相加。"
      },
      {
       "type": "example",
       "title": "例題：46 × 27",
       "html": "第一步：46 × 7 = 322（個位相乘）。<br>第二步：46 × 20 = 920（用十位的 2 乘，補一個 0）。<br>第三步：322 + 920 = <b>1242</b>。<br>檢查：46 接近 50，27 接近 30，50 × 30 = 1500，答案 1242 接近 1500，合理。"
      },
      {
       "type": "tip",
       "html": "常犯錯誤：用十位相乘時忘記補 0，把 46 × 2 直接寫在個位，結果少了十倍。第二行必須向左移一格。"
      },
      {
       "type": "text",
       "html": "乘法交換性質在兩位數乘法同樣成立：46 × 27 = 27 × 46。選擇較小的數作第二個因數，直式會短一些，較少出錯。"
      }
     ],
