     "teaching": [
      {
       "type": "text",
       "html": "<b>周界</b>是圍繞圖形一圈的長度，單位是厘米 (cm)；<b>面積</b>是圖形所佔平面的大小，單位是平方厘米 (cm<sup>2</sup>)。兩者意義不同，不可以混淆。"
      },
      {
       "type": "formula",
       "html": "長方形周界 = (長 + 闊) × 2　　長方形面積 = 長 × 闊<br>正方形周界 = 邊長 × 4　　正方形面積 = 邊長 × 邊長"
      },
      {
       "type": "text",
       "html": "面積公式的原理：長方形內可以排滿 1 cm<sup>2</sup> 的小正方形，每行有「長」個，共「闊」行，所以總數是長 × 闊。"
      },
      {
       "type": "example",
       "title": "例題：長 6 cm、闊 4 cm 的長方形",
       "html": "周界 = (6 + 4) × 2 = 10 × 2 = <b>20 cm</b>。<br>面積 = 6 × 4 = <b>24 cm<sup>2</sup></b>。<br>如果只知道正方形周界是 36 cm，邊長 = 36 ÷ 4 = 9 cm，面積 = 9 × 9 = 81 cm<sup>2</sup>。"
      },
      {
       "type": "tip",
       "html": "常犯錯誤：把周界和面積的公式調轉用；或面積的單位寫成 cm 而不是 cm<sup>2</sup>。答案要同時檢查數值和單位。"
      },
      {
       "type": "text",
       "html": "周界相同，面積可以不同：長 8 cm 闊 2 cm 與長 6 cm 闊 4 cm 的長方形，周界都是 20 cm，但面積分別是 16 cm<sup>2</sup> 和 24 cm<sup>2</sup>。"
      }
     ],
     "keywords": [
      "周界",
      "面積",
      "平方厘米",
      "邊長"
     ]
