    {
     "id": "p6-u8",
     "title": "綜合應用與數學建模",
     "en": "Integrated Applications and Mathematical Modelling",
     "strand": "數與代數",
     "objectives": [
      "能從情境中找出已知條件與未知量",
      "能作合理假設並建立數學模型",
      "能綜合運用不同單位的知識解決問題",
      "能檢驗答案並解釋結果的合理性"
     ],
     "teaching": [
      {
       "type": "text",
       "html": "數學建模（mathematical modelling）是把真實情境「翻譯」成數學的四步：理解問題 → 假設與簡化 → 建立算式 → 驗證與解釋。真實問題的資料往往不齊全，所以要說明自己的假設。"
      },
      {
       "type": "formula",
       "html": "建模四步：① 找出要答的問題；② 列出已知數據與假設（例如不計損耗、不計餘數）；③ 選公式或列方程；④ 代入計算，檢查單位與合理性。"
      },
      {
       "type": "example",
       "title": "例題：40 人班會旅行的每人費用",
       "html": "旅遊車租金 $2 400、門票每位 $25、午餐每位 $18，另加雜費 $600。<br>① 總支出 = 2 400 + 40 × 25 + 40 × 18 + 600。<br>② = 2 400 + 1 000 + 720 + 600 = 4 720 元。<br>③ 每人應付 = 4 720 ÷ 40 = <b>118 元</b>。<br>④ 檢查：118 × 40 = 4 720，剛好收回成本。"
      },
      {
       "type": "tip",
       "html": "常犯錯誤：把「每位」的收費只計一次（40 × 25 寫成 25），或忘記把一次性的費用（租金）分攤給所有人。看清楚哪些是按人計、哪些是總額。"
      },
      {
       "type": "text",
       "html": "常見的跨單元組合：先求底面積再乘高得體積；先求速率再乘時間得距離；先求折扣後售價再計百分增減。解題時先問「下一步需要甚麼量」，再決定用哪條公式。"
      },
      {
       "type": "example",
       "title": "例題：圓柱水桶的水可裝滿多少瓶",
       "html": "圓柱形水桶內半徑 20 cm、高 50 cm（π = 3.14），注滿水後倒入每瓶 500 mL 的水瓶。<br>① 水桶體積 = 3.14 × 20 × 20 × 50 = 62 800 cm³。<br>② 1 cm³ = 1 mL，即 62 800 mL。<br>③ 62 800 ÷ 500 = 125.6。<br>④ 最多可裝滿 <b>125 瓶</b>（不足一瓶不能算作一瓶，要取整數部分）。"
      }
     ],
     "keywords": [
      "數學建模",
      "假設",
      "綜合應用",
      "合理性"
     ]
    }
